using System;
using System.Threading;
using System.Threading.Tasks;

/// <summary>
/// Migrated from .NET Framework to .NET 8.
/// Thread.Abort throws PlatformNotSupportedException in .NET 6+.
/// All patterns replaced with cooperative CancellationToken.
/// </summary>
public class BackgroundProcessor : IDisposable
{
    private Thread? _workerThread;
    private CancellationTokenSource? _cts;

    public void Start()
    {
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _workerThread = new Thread(() => ProcessLoop(token));
        _workerThread.IsBackground = true;
        _workerThread.Start();
    }

    private void ProcessLoop(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            try
            {
                var item = GetNextItem(token); // pass token so blocking calls can be interrupted
                ProcessItem(item, token);
            }
            catch (OperationCanceledException) when (token.IsCancellationRequested)
            {
                // Replaces catch (ThreadAbortException)
                RollbackCurrentTransaction();
                // No need for ResetAbort — cooperative cancellation doesn't rethrow.
                // Loop condition will exit naturally.
            }
            finally
            {
                FlushBuffers();
            }
        }
    }

    public void Stop()
    {
        if (_cts is null || _workerThread is null)
            return;

        _cts.Cancel(); // signals the token — replaces Thread.Abort

        // Give the thread time to finish gracefully.
        // Join is cleaner than Sleep + IsAlive polling.
        if (!_workerThread.Join(TimeSpan.FromSeconds(2)))
        {
            // Thread didn't exit in time. With cooperative cancellation
            // this means GetNextItem or ProcessItem isn't checking the
            // token. See "What if the thread won't stop?" below.
            Console.Error.WriteLine("Worker thread did not exit within timeout.");
        }
    }

    public void Dispose()
    {
        Stop();
        _cts?.Dispose();
        _cts = null;
    }

    // --- Stubs: update these to accept CancellationToken too ---
    private object GetNextItem(CancellationToken token) => throw new NotImplementedException();
    private void ProcessItem(object item, CancellationToken token) => throw new NotImplementedException();
    private void RollbackCurrentTransaction() { }
    private void FlushBuffers() { }
}

